#[derive(Debug)]
pub struct SceneBuilder {
    pub(crate) owner: u64,
    pub(crate) source: SourceOwner,
    pub(crate) generation: u64,
    pub(crate) scenes: Vec<SceneData>,
    pub(crate) animation: OwnedAnimation,
    pub(crate) ignored: [Ignored; 4],
    pub(crate) stats: MemoryStats,
    pub(crate) limits: Limits,
    pub(crate) drafts: [Option<crate::draft::ActiveDraft>; 64],
    pub(crate) draft_depth: usize,
    next_serial: u64,
    root: SceneId,
}

macro_rules! room {
    ($self:ident,$index:expr,$field:ident,$extra:expr,$cap:expr,$pending:expr) => {{
        let pending = $pending;
        let current = add($self.stats.live_bytes, pending)?;
        let available = $self
            .limits
            .reserved_bytes
            .checked_sub(current)
            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
        // Check all counters before the mutating reserve can transfer old values.
        let history_room = usize::MAX - $self.stats.total_allocated_bytes;
        let available = available.min(history_room);
        if $self.stats.allocation_count == usize::MAX {
            return Err(arithmetic());
        }
        let (new, old) = reserve(&mut $self.scenes[$index].$field, $extra, $cap, available)?;
        if new != 0 {
            $self.stats.peak_live_bytes = $self.stats.peak_live_bytes.max(add(current, new)?);
            $self.stats.total_allocated_bytes = add($self.stats.total_allocated_bytes, new)?;
            $self.stats.allocation_count += 1;
            $self.stats.live_bytes = add($self.stats.live_bytes - old, new)?;
        }
    }};
}
pub(crate) use room;

impl SceneBuilder {
    pub fn new(
        source: SourceOwner,
        animation: OwnedAnimation,
        generation: u64,
        viewport: Viewport,
        limits: Limits,
    ) -> Result<Self> {
        let limits = limits.effective();
        if !std::sync::Arc::ptr_eq(&source, animation.source_owner()) {
            return Err(invalid(0));
        }
        if source.len() > limits.source_bytes {
            return Err(limit(LimitKind::SourceBytes));
        }
        crate::validate::viewport(viewport)?;
        let live = animation.storage_bytes().ok_or_else(arithmetic)?;
        if live > limits.reserved_bytes {
            return Err(limit(LimitKind::ReservedBytes));
        }
        let owner = NEXT_OWNER
            .try_update(Ordering::Relaxed, Ordering::Relaxed, |v| v.checked_add(1))
            .map_err(|_| arithmetic())?;
        let root = SceneId {
            owner,
            slot: 0,
            serial: 1,
        };
        let mut value = Self {
            owner,
            source,
            generation,
            scenes: Vec::new(),
            animation,
            ignored: [Ignored::default(); 4],
            stats: MemoryStats {
                source_bytes: live,
                live_bytes: live,
                peak_live_bytes: live,
                total_allocated_bytes: 0,
                allocation_count: 0,
            },
            limits,
            drafts: [None; 64],
            draft_depth: 0,
            next_serial: 1,
            root,
        };
        value.stats.source_bytes = value.source.capacity();
        let actual = value.reserve_scene()?;
        value.scenes.push(SceneData::new(actual.serial, viewport));
        value.root = actual;
        Ok(value)
    }
    fn reserve_scene(&mut self) -> Result<SceneId> {
        let serial = self.serial()?;
        let available = self
            .limits
            .reserved_bytes
            .checked_sub(self.stats.live_bytes)
            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
        if self.stats.allocation_count == usize::MAX {
            return Err(arithmetic());
        }
        let (new, old) = reserve(
            &mut self.scenes,
            1,
            self.limits.scenes,
            available.min(usize::MAX - self.stats.total_allocated_bytes),
        )?;
        if new != 0 {
            self.stats.peak_live_bytes = self
                .stats
                .peak_live_bytes
                .max(add(self.stats.live_bytes, new)?);
            self.stats.live_bytes = add(self.stats.live_bytes - old, new)?;
            self.stats.total_allocated_bytes = add(self.stats.total_allocated_bytes, new)?;
            self.stats.allocation_count += 1;
        }
        Ok(SceneId {
            owner: self.owner,
            slot: self.scenes.len() as u32,
            serial,
        })
    }
    pub(crate) fn serial(&mut self) -> Result<u64> {
        let serial = self.next_serial;
        self.next_serial = self.next_serial.checked_add(1).ok_or_else(arithmetic)?;
        Ok(serial)
    }
    pub(crate) fn index(&self, id: SceneId) -> Result<usize> {
        let scene = self.scenes.get(id.index()).ok_or_else(|| invalid(0))?;
        if id.owner != self.owner || id.serial != scene.serial {
            return Err(invalid(0));
        }
        Ok(id.index())
    }
    pub(crate) fn writable(&self, id: SceneId) -> Result<usize> {
        let index = self.index(id)?;
        if self.scenes[index].sealed || self.active_draft().is_some_and(|draft| draft.scene != id) {
            return Err(invalid(0));
        }
        Ok(index)
    }
    pub fn source_owner(&self) -> &SourceOwner {
        &self.source
    }
    pub fn root_id(&self) -> SceneId {
        self.root
    }
    pub fn scene(&self, id: SceneId) -> Result<SceneView<'_>> {
        let i = self.index(id)?;
        Ok(self.scenes[i].view(
            self.owner,
            i,
            &self.scenes,
            &self.source,
            self.animation.view(),
            self.ignored,
        ))
    }
    pub fn memory_stats(&self) -> MemoryStats {
        self.stats
    }
    pub fn new_scene(&mut self, viewport: Viewport) -> Result<SceneId> {
        crate::validate::viewport(viewport)?;
        let id = self.reserve_scene()?;
        self.scenes.push(SceneData::new(id.serial, viewport));
        Ok(id)
    }
    pub fn mark(&self, scene: SceneId) -> Result<BuildMark> {
        if self.draft_depth != 0 {
            return Err(invalid(0));
        }
        self.checkpoint_internal(scene)
    }
    pub(crate) fn checkpoint_internal(&self, scene: SceneId) -> Result<BuildMark> {
        self.writable(scene)?;
        self.checkpoint_unrestricted(scene)
    }
    pub(crate) fn checkpoint_unrestricted(&self, scene: SceneId) -> Result<BuildMark> {
        let i = self.index(scene)?;
        Ok(BuildMark {
            scene,
            epoch: self.scenes[i].epoch,
            image_pixels: self.scenes[i].image_pixels,
            lengths: self.scenes[i].lengths(),
            publications: self.scenes[i].publications.len(),
        })
    }
    pub fn rollback(&mut self, mark: BuildMark) -> Result<()> {
        if self.draft_depth != 0 {
            return Err(invalid(0));
        }
        self.rollback_internal(mark)
    }
    pub(crate) fn rollback_internal(&mut self, mark: BuildMark) -> Result<()> {
        let i = self.writable(mark.scene)?;
        let scene = &self.scenes[i];
        if scene.publications.len() < mark.publications
            || scene.epoch != mark.epoch
            || scene
                .lengths()
                .iter()
                .zip(mark.lengths)
                .any(|(now, then)| *now < then)
        {
            return Err(invalid(0));
        }
        let epoch = scene.epoch.checked_add(1).ok_or_else(arithmetic)?;
        let before = scene.storage_bytes()?;
        self.scenes[i].truncate(mark.lengths);
        self.scenes[i]
            .publications
            .retain(|p| p.order < mark.publications);
        self.scenes[i].epoch = epoch;
        self.scenes[i].image_pixels = mark.image_pixels;
        let after = self.scenes[i].storage_bytes()?;
        self.stats.live_bytes = self.stats.live_bytes - (before - after);
        Ok(())
    }
    /// Seal children before linking them from masks. No mutable child can escape.
    pub fn seal(&mut self, id: SceneId, control: &mut dyn WorkControl) -> Result<()> {
        let i = self.index(id)?;
        if self.scenes[i].sealed
            || self.drafts[..self.draft_depth]
                .iter()
                .flatten()
                .any(|d| d.scene == id)
            || self
                .active_draft()
                .is_some_and(|d| id.index() < d.scene_count)
        {
            return Err(invalid(0));
        }
        crate::validate::scene(self, id, control)?;
        self.scenes[i].sealed = true;
        Ok(())
    }
    pub fn freeze(self) -> Result<SceneGraph> {
        self.freeze_controlled(&mut NoStop)
    }
    pub fn freeze_controlled(mut self, control: &mut dyn WorkControl) -> Result<SceneGraph> {
        control.checkpoint().map_err(stopped)?;
        if self.draft_depth != 0 {
            return Err(invalid(0));
        }
        for i in 0..self.scenes.len() {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            let id = SceneId {
                owner: self.owner,
                slot: i as u32,
                serial: self.scenes[i].serial,
            };
            crate::validate::scene(&self, id, control)?;
            self.scenes[i].sealed = true;
        }
        let mut measured = add(
            self.animation.storage_bytes().ok_or_else(arithmetic)?,
            bytes(&self.scenes)?,
        )?;
        for scene in &self.scenes {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            measured = add(measured, scene.storage_bytes_controlled(control)?)?;
        }
        if measured != self.stats.live_bytes || measured > self.limits.reserved_bytes {
            return Err(invalid(0));
        }
        Ok(SceneGraph {
            owner: self.owner,
            source: self.source,
            generation: self.generation,
            root: self.root,
            scenes: self.scenes,
            animation: self.animation,
            ignored: self.ignored,
            stats: self.stats,
        })
    }
    /// Record a global diagnostic in the innermost active draft, if any.
    /// Draft rollback restores both counts and first offsets; child commit
    /// retains its notices within the parent transaction.
    pub fn record_ignored(&mut self, kind: IgnoredKind, offset: usize) -> Result<()> {
        if offset > self.source.len() {
            return Err(invalid(offset));
        }
        let record = &mut self.ignored[kind as usize];
        record.count = record.count.checked_add(1).ok_or_else(arithmetic)?;
        if record.first_offset.is_none() {
            record.first_offset = Some(offset);
        }
        Ok(())
    }
    pub(crate) fn pending(&mut self, bytes: usize) -> Result<()> {
        let total = add(self.stats.live_bytes, bytes)?;
        if total > self.limits.reserved_bytes {
            return Err(limit(LimitKind::ReservedBytes));
        }
        self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(total);
        Ok(())
    }
    pub(crate) fn retain(&mut self, bytes: usize) -> Result<()> {
        // All arithmetic and budget checks must precede any table publication.
        let live = add(self.stats.live_bytes, bytes)?;
        let total = add(self.stats.total_allocated_bytes, bytes)?;
        let count = self
            .stats
            .allocation_count
            .checked_add(usize::from(bytes != 0))
            .ok_or_else(arithmetic)?;
        if live > self.limits.reserved_bytes {
            return Err(limit(LimitKind::ReservedBytes));
        }
        self.stats.live_bytes = live;
        self.stats.total_allocated_bytes = total;
        self.stats.allocation_count = count;
        Ok(())
    }
}
pub(crate) struct NoStop;
impl WorkControl for NoStop {
    fn charge(&mut self, _: WorkKind, _: u64) -> std::result::Result<(), Stop> {
        Ok(())
    }
    fn checkpoint(&mut self) -> std::result::Result<(), Stop> {
        Ok(())
    }
}
//! Scoped decoder draft authorization. Tokens contain values, not builder
//! borrows, so an engine can own its builder and pending draft without selfrefs.
use crate::types::{invalid, stopped};
use crate::*;
#[derive(Debug, Clone, Copy)]
pub(crate) struct ActiveDraft {
    pub scene: SceneId,
    pub nonce: u64,
    pub scene_count: usize,
}
#[derive(Debug)]
pub struct DraftToken {
    pub(crate) mark: BuildMark,
    pub(crate) nonce: u64,
    pub(crate) scene_count: usize,
    ignored: [Ignored; 4],
}
impl SceneBuilder {
    pub fn begin_draft(&mut self, scene: SceneId) -> Result<DraftToken> {
        let i = self.index(scene)?;
        if self.scenes[i].sealed || self.draft_depth >= 64 {
            return Err(invalid(0));
        }
        if let Some(parent) = self.active_draft() {
            if scene.index() < parent.scene_count {
                return Err(invalid(0));
            }
        }
        let nonce = self.serial()?;
        let mark = self.checkpoint_unrestricted(scene)?;
        let scene_count = self.scenes.len();
        self.drafts[self.draft_depth] = Some(ActiveDraft {
            scene,
            nonce,
            scene_count,
        });
        self.draft_depth += 1;
        Ok(DraftToken {
            mark,
            nonce,
            scene_count,
            ignored: self.ignored,
        })
    }
    pub(crate) fn active_draft(&self) -> Option<ActiveDraft> {
        self.draft_depth.checked_sub(1).and_then(|i| self.drafts[i])
    }
    pub(crate) fn draft_index(&self, token: &DraftToken) -> Result<usize> {
        let active = self.active_draft().ok_or_else(|| invalid(0))?;
        if active.scene != token.mark.scene
            || active.nonce != token.nonce
            || active.scene_count != token.scene_count
        {
            return Err(invalid(0));
        }
        let i = self.index(active.scene)?;
        if self.scenes[i].sealed {
            return Err(invalid(0));
        }
        if self.scenes[i]
            .lengths()
            .iter()
            .zip(token.mark.lengths)
            .any(|(now, then)| *now < then)
        {
            return Err(invalid(0));
        }
        Ok(i)
    }
    pub(crate) fn draft_slot(
        &self,
        token: &DraftToken,
        table: usize,
        slot: usize,
        len: usize,
    ) -> Result<usize> {
        let i = self.draft_index(token)?;
        if slot < token.mark.lengths[table] || slot >= len {
            return Err(invalid(0));
        }
        Ok(i)
    }
    /// Validation failure/cancellation leaves the token active and rollbackable.
    pub fn commit_draft(
        &mut self,
        token: &DraftToken,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.draft_index(token)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::scene(self, token.mark.scene, control)?;
        self.draft_depth -= 1;
        self.drafts[self.draft_depth] = None;
        Ok(())
    }
    /// Rollback includes all descendants created after this graph checkpoint.
    /// Cleanup is unconditional even when the caller's work control has stopped.
    pub fn rollback_draft(&mut self, mut token: DraftToken) -> Result<()> {
        let i = self.draft_index(&token)?;
        let mut released = 0;
        for scene in &self.scenes[token.scene_count..] {
            released = crate::memory::add(released, scene.storage_bytes()?)?;
        }
        token.mark.epoch = self.scenes[i].epoch;
        self.rollback_internal(token.mark)?;
        self.scenes.truncate(token.scene_count);
        self.stats.live_bytes -= released;
        self.ignored = token.ignored;
        self.draft_depth -= 1;
        self.drafts[self.draft_depth] = None;
        Ok(())
    }
}
use crate::builder::room;
use crate::memory::{add, bytes};
use crate::types::{invalid, limit, stopped};
use crate::*;
impl SceneBuilder {
    pub fn finalize_shape(
        &mut self,
        token: &DraftToken,
        id: ShapeId,
        value: Shape,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 3, id.index(), self.scenes[i].shapes.len())?;
        let old = self
            .scene(token.mark.scene)?
            .shape(id)
            .ok_or_else(|| invalid(0))?;
        if old.edges != value.edges
            || old.subpaths != value.subpaths
            || old.source.element != value.source.element
        {
            return Err(invalid(0));
        }
        control.checkpoint().map_err(stopped)?;
        crate::validate::shape_attributes(self, token.mark.scene, &value, control)?;
        self.scenes[i].shapes[id.index()] = value;
        Ok(())
    }
    pub fn finalize_shape_colors(
        &mut self,
        token: &DraftToken,
        id: ShapeId,
        colors: &[[u8; 4]],
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 3, id.index(), self.scenes[i].shapes.len())?;
        let shape = self
            .scene(token.mark.scene)?
            .shape(id)
            .ok_or_else(|| invalid(0))?;
        let range = shape.edges;
        if range.count != colors.len() || range.first < token.mark.lengths[1] {
            return Err(invalid(0));
        }
        range.require(self.scenes[i].edge_colors.len(), 0)?;
        control.checkpoint().map_err(stopped)?;
        for _ in colors {
            control.charge(WorkKind::PaintVisit, 1).map_err(stopped)?;
        }
        self.scenes[i].edge_colors[range.first..range.end().ok_or_else(|| invalid(0))?]
            .copy_from_slice(colors);
        Ok(())
    }
    pub fn finalize_transform(
        &mut self,
        token: &DraftToken,
        id: TransformId,
        value: TransformFrame,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 7, id.index(), self.scenes[i].transforms.len())?;
        let old = self
            .scene(token.mark.scene)?
            .transform(id)
            .ok_or_else(|| invalid(0))?;
        if old.parent != value.parent || old.source_offset != value.source_offset {
            return Err(invalid(0));
        }
        control.checkpoint().map_err(stopped)?;
        crate::validate::transform(self, token.mark.scene, &value, control)?;
        self.scenes[i].transforms[id.index()] = value;
        Ok(())
    }
    pub fn finalize_clip(
        &mut self,
        token: &DraftToken,
        id: ClipId,
        value: Clip,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 18, id.index(), self.scenes[i].clips.len())?;
        let old = self
            .scene(token.mark.scene)?
            .clip(id)
            .ok_or_else(|| invalid(0))?;
        if old.parent != value.parent {
            return Err(invalid(0));
        }
        let old_bytes = add(bytes(&old.geometry.edges)?, bytes(&old.geometry.shapes)?)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::clip(self, token.mark.scene, &value, control)?;
        let new = add(
            bytes(&value.geometry.edges)?,
            bytes(&value.geometry.shapes)?,
        )?;
        self.pending(new)?;
        self.retain(new)?;
        self.scenes[i].clips[id.index()] = value;
        self.stats.live_bytes -= old_bytes;
        Ok(())
    }
    pub fn finalize_mask(
        &mut self,
        token: &DraftToken,
        id: MaskId,
        value: Mask,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 12, id.index(), self.scenes[i].masks.len())?;
        self.scene(token.mark.scene)?
            .mask(id)
            .ok_or_else(|| invalid(0))?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::mask(self, token.mark.scene, &value, control)?;
        self.scenes[i].masks[id.index()] = value;
        Ok(())
    }
    pub fn finalize_group(
        &mut self,
        token: &DraftToken,
        id: GroupId,
        value: OpacityGroup,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 9, id.index(), self.scenes[i].groups.len())?;
        let old = self
            .scene(token.mark.scene)?
            .group(id)
            .ok_or_else(|| invalid(0))?;
        if old.parent != value.parent || old.shapes.first != value.shapes.first {
            return Err(invalid(0));
        }
        control.checkpoint().map_err(stopped)?;
        crate::validate::group(self, token.mark.scene, &value, id.index(), control)?;
        self.scenes[i].groups[id.index()] = value;
        Ok(())
    }
    pub fn finalize_fill_paint(
        &mut self,
        token: &DraftToken,
        index: usize,
        value: Paint,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.finalize_paint(token, index, value, true, control)
    }
    pub fn finalize_stroke_paint(
        &mut self,
        token: &DraftToken,
        index: usize,
        value: Paint,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.finalize_paint(token, index, value, false, control)
    }
    fn finalize_paint(
        &mut self,
        token: &DraftToken,
        index: usize,
        value: Paint,
        fill: bool,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        let (table, len) = if fill {
            (14, self.scenes[i].fill_paints.len())
        } else {
            (15, self.scenes[i].stroke_paints.len())
        };
        self.draft_slot(token, table, index, len)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::paint(self, token.mark.scene, &value, control)?;
        if fill {
            self.scenes[i].fill_paints[index] = value;
        } else {
            self.scenes[i].stroke_paints[index] = value;
        }
        Ok(())
    }
    pub fn finalize_filter(
        &mut self,
        token: &DraftToken,
        id: FilterId,
        mut value: Filter,
        primitives: &[FilterPrimitive],
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 10, id.index(), self.scenes[i].filters.len())?;
        self.scene(token.mark.scene)?
            .filter(id)
            .ok_or_else(|| invalid(0))?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::filter(value, primitives, control)?;
        for p in primitives {
            control.charge(WorkKind::FilterPixel, 1).map_err(stopped)?;
            if p.source_offset > self.source.len() {
                return Err(invalid(p.source_offset));
            }
        }
        if add(self.scenes[i].filter_primitives.len(), primitives.len())? > 65536 {
            return Err(limit(LimitKind::Filters));
        }
        room!(self, i, filter_primitives, primitives.len(), 65536, 0);
        control.checkpoint().map_err(stopped)?;
        value.primitives = TableRange {
            first: self.scenes[i].filter_primitives.len(),
            count: primitives.len(),
        };
        self.scenes[i]
            .filter_primitives
            .extend_from_slice(primitives);
        self.scenes[i].filters[id.index()] = value;
        Ok(())
    }
}

//! Per-job capacity admission. Reservations are explicit leases; consumers
//! release them when the corresponding owned buffers leave the job. This is
//! accounting over caller-owned allocations, not a global allocator hook.
use crate::memory::{add, arithmetic, bytes, reserve};
use crate::types::{invalid, limit};
use crate::*;
use std::sync::atomic::{AtomicU64, Ordering};
static NEXT_LEDGER: AtomicU64 = AtomicU64::new(1);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(usize)]
pub enum AllocationTag {
    None,
    TokenArray,
    ReferenceIndex,
    ClipCopy,
    Output,
}
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct RenderWorkStats {
    pub shape_pixels: u64,
    pub shape_samples: u64,
    pub fill_edge_tests: u64,
    pub fill_interval_tests: u64,
    pub stroke_tests: u64,
    pub scanline_edge_entries: u64,
    pub shape_row_visits: u64,
    pub boundary_mark_work: u64,
    pub total_work: u64,
}
impl RenderWorkStats {
    pub fn charge(&mut self, kind: WorkKind, units: u64) -> Result<()> {
        let total = self.total_work.checked_add(units).ok_or_else(arithmetic)?;
        let target = match kind {
            WorkKind::ShapePixel => Some(&mut self.shape_pixels),
            WorkKind::ShapeSample => Some(&mut self.shape_samples),
            WorkKind::FillEdgeTest => Some(&mut self.fill_edge_tests),
            WorkKind::FillIntervalTest => Some(&mut self.fill_interval_tests),
            WorkKind::StrokeTest => Some(&mut self.stroke_tests),
            WorkKind::ScanlineEdgeEntry => Some(&mut self.scanline_edge_entries),
            WorkKind::ShapeRowVisit => Some(&mut self.shape_row_visits),
            WorkKind::BoundaryMark => Some(&mut self.boundary_mark_work),
            _ => None,
        };
        if let Some(value) = target {
            *value = value.checked_add(units).ok_or_else(arithmetic)?;
        }
        self.total_work = total;
        Ok(())
    }
}
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct RenderMemoryStats {
    pub peak_live_bytes: usize,
    pub live_bytes: usize,
    pub total_allocated_bytes: usize,
    pub allocation_count: usize,
    pub source_bytes: usize,
    pub token_array_bytes: usize,
    pub reference_index_bytes: usize,
    pub clip_copy_bytes: usize,
    pub output_bytes: usize,
    pub overflow: bool,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AllocationLease {
    owner: u64,
    slot: usize,
    serial: u64,
}
#[derive(Debug, Clone, Copy)]
struct Entry {
    serial: u64,
    tag: AllocationTag,
    bytes: usize,
    active: bool,
    next_free: Option<usize>,
}
#[derive(Debug)]
pub struct ChargeLedger {
    source: SourceOwner,
    owner: u64,
    next: u64,
    max_leases: usize,
    reserved_bytes: usize,
    per_tag: [usize; 5],
    entries: Vec<Entry>,
    free: Option<usize>,
    stats: RenderMemoryStats,
    pub work: RenderWorkStats,
}
impl ChargeLedger {
    pub fn new(source: &SourceOwner, reserved_bytes: usize, max_leases: usize) -> Result<Self> {
        if source.len() > 1 << 30 {
            return Err(limit(LimitKind::SourceBytes));
        }
        if source.capacity() > reserved_bytes {
            return Err(limit(LimitKind::ReservedBytes));
        }
        let owner = NEXT_LEDGER
            .try_update(Ordering::Relaxed, Ordering::Relaxed, |v| v.checked_add(1))
            .map_err(|_| arithmetic())?;
        let source_bytes = source.capacity();
        Ok(Self {
            source: source.clone(),
            owner,
            next: 1,
            max_leases,
            reserved_bytes,
            per_tag: [0; 5],
            entries: Vec::new(),
            free: None,
            stats: RenderMemoryStats {
                live_bytes: source_bytes,
                peak_live_bytes: source_bytes,
                source_bytes,
                ..Default::default()
            },
            work: Default::default(),
        })
    }
    pub fn source_owner(&self) -> &SourceOwner {
        &self.source
    }
    pub fn available(&self) -> usize {
        self.reserved_bytes - self.stats.live_bytes
    }
    pub fn stats(&self) -> RenderMemoryStats {
        let mut s = self.stats;
        s.token_array_bytes = self.per_tag[1];
        s.reference_index_bytes = self.per_tag[2];
        s.clip_copy_bytes = self.per_tag[3];
        s.output_bytes = self.per_tag[4];
        s
    }
    /// Capacity supplied by an actual Vec, not logical element count.
    pub fn admit_vec<T>(&mut self, tag: AllocationTag, values: &Vec<T>) -> Result<AllocationLease> {
        self.admit(tag, bytes(values)?)
    }
    /// Aggregate nested capacity computed by the full owning module (e.g. scratch).
    /// Callers retain the buffer and release its lease at the same lifetime boundary.
    pub fn admit(&mut self, tag: AllocationTag, amount: usize) -> Result<AllocationLease> {
        match self.admit_inner(tag, amount) {
            Err(error) if error.kind == ErrorKind::Limit(LimitKind::Arithmetic) => {
                self.stats.overflow = true;
                Err(error)
            }
            result => result,
        }
    }
    fn admit_inner(&mut self, tag: AllocationTag, amount: usize) -> Result<AllocationLease> {
        let next = self.next.checked_add(1).ok_or_else(arithmetic)?;
        let count = self
            .stats
            .allocation_count
            .checked_add(usize::from(amount != 0))
            .ok_or_else(arithmetic)?;
        let tagged = add(self.per_tag[tag as usize], amount)?;
        let history = add(self.stats.total_allocated_bytes, amount)?;
        let total = add(self.stats.live_bytes, amount)?;
        let overlap = self
            .reserved_bytes
            .checked_sub(total)
            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
        if self.free.is_none() {
            count.checked_add(1).ok_or_else(arithmetic)?;
            let (new, old) = reserve(
                &mut self.entries,
                1,
                self.max_leases,
                overlap.min(usize::MAX - history),
            )?;
            if new != 0 {
                let current = add(total, new)?;
                let new_history = add(history, new)?;
                let new_count = count.checked_add(1).ok_or_else(arithmetic)?;
                self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(current);
                self.stats.live_bytes = add(self.stats.live_bytes - old, new)?;
                self.per_tag[0] = add(self.per_tag[0] - old, new)?;
                self.stats.total_allocated_bytes = new_history - amount;
                self.stats.allocation_count = new_count - usize::from(amount != 0);
            }
        }
        // Recalculate after registry growth. Metadata is itself retained and charged.
        let current = add(self.stats.live_bytes, amount)?;
        if current > self.reserved_bytes {
            return Err(limit(LimitKind::ReservedBytes));
        }
        let serial = self.next;
        self.next = next;
        let slot = if let Some(slot) = self.free {
            self.free = self.entries[slot].next_free;
            slot
        } else {
            self.entries.len()
        };
        let entry = Entry {
            serial,
            tag,
            bytes: amount,
            active: true,
            next_free: None,
        };
        if slot == self.entries.len() {
            self.entries.push(entry);
        } else {
            self.entries[slot] = entry;
        }
        self.per_tag[tag as usize] = if tag == AllocationTag::None {
            add(self.per_tag[0], amount)?
        } else {
            tagged
        };
        self.stats.live_bytes = current;
        self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(current);
        self.stats.total_allocated_bytes = add(self.stats.total_allocated_bytes, amount)?;
        self.stats.allocation_count = self
            .stats
            .allocation_count
            .checked_add(usize::from(amount != 0))
            .ok_or_else(arithmetic)?;
        Ok(AllocationLease {
            owner: self.owner,
            slot,
            serial,
        })
    }
    pub fn release(&mut self, lease: AllocationLease) -> Result<()> {
        if lease.owner != self.owner {
            return Err(invalid(0));
        }
        let entry = self.entries.get_mut(lease.slot).ok_or_else(|| invalid(0))?;
        if !entry.active || entry.serial != lease.serial {
            return Err(invalid(0));
        }
        entry.active = false;
        self.per_tag[entry.tag as usize] -= entry.bytes;
        self.stats.live_bytes -= entry.bytes;
        entry.next_free = self.free;
        self.free = Some(lease.slot);
        Ok(())
    }
}

impl ChargeLedger {
    pub(crate) fn identity(&self) -> u64 {
        self.owner
    }

    /// A zero-copy replacement allocator used only by the owning job. The
    /// active entry reserves requested bytes before Vec::try_reserve_exact;
    /// exclusive ledger access also holds the remaining overlap budget in escrow
    /// until the actual capacity has been checked and the lease finalized.
    pub(crate) fn allocate<T>(
        &mut self,
        tag: AllocationTag,
        capacity: usize,
        control: &mut dyn WorkControl,
    ) -> Result<(Vec<T>, AllocationLease)> {
        control.checkpoint().map_err(crate::types::stopped)?;
        let requested = capacity
            .checked_mul(std::mem::size_of::<T>())
            .ok_or_else(arithmetic)?;
        // Mint a zero lease first: registry growth is admitted before payload
        // allocation, and retained even when payload allocation subsequently fails.
        let lease = self.admit(tag, 0)?;
        let result = (|| {
            if requested > self.available() {
                return Err(limit(LimitKind::ReservedBytes));
            }
            add(self.stats.total_allocated_bytes, requested)?;
            self.stats
                .allocation_count
                .checked_add(usize::from(requested != 0))
                .ok_or_else(arithmetic)?;
            let tagged_reservation = add(self.per_tag[tag as usize], requested)?;
            let live_reservation = add(self.stats.live_bytes, requested)?;
            // The active registry entry is a real pre-allocation reservation.
            // Failure releases it; only successful physical reserves enter history.
            self.entries[lease.slot].bytes = requested;
            self.per_tag[tag as usize] = tagged_reservation;
            self.stats.live_bytes = live_reservation;
            let mut values = Vec::new();
            values.try_reserve_exact(capacity).map_err(|_| Diagnostic {
                kind: ErrorKind::OutOfMemory,
                offset: 0,
            })?;
            let actual = bytes(&values)?;
            // Vec may report excess capacity. No values are transferred or
            // published until actual capacity and history pass the SAME budget.
            let history = add(self.stats.total_allocated_bytes, actual)?;
            let count = self
                .stats
                .allocation_count
                .checked_add(usize::from(actual != 0))
                .ok_or_else(arithmetic)?;
            self.stats.total_allocated_bytes = history;
            self.stats.allocation_count = count;
            let escrow = add(requested, self.available())?;
            if actual > escrow {
                return Err(limit(LimitKind::ReservedBytes));
            }
            let tagged = add(self.per_tag[tag as usize] - requested, actual)?;
            let live = add(self.stats.live_bytes - requested, actual)?;
            self.entries[lease.slot].bytes = actual;
            self.per_tag[tag as usize] = tagged;
            self.stats.live_bytes = live;
            self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(live);
            control.checkpoint().map_err(crate::types::stopped)?;
            Ok(values)
        })();
        match result {
            Ok(values) => Ok((values, lease)),
            Err(e) => {
                self.release(lease)?;
                if e.kind == ErrorKind::Limit(LimitKind::Arithmetic) {
                    self.stats.overflow = true;
                }
                Err(e)
            }
        }
    }
    pub(crate) fn empty_lease(&mut self, lease: AllocationLease) -> Result<()> {
        if lease.owner != self.owner {
            return Err(invalid(0));
        }
        let entry = self.entries.get_mut(lease.slot).ok_or_else(|| invalid(0))?;
        if !entry.active || entry.serial != lease.serial {
            return Err(invalid(0));
        }
        self.stats.live_bytes -= entry.bytes;
        self.per_tag[entry.tag as usize] -= entry.bytes;
        entry.bytes = 0;
        Ok(())
    }
}
impl ChargeLedger {
    pub(crate) fn require_no_leases(&self) -> Result<()> {
        if self.entries.iter().any(|e| e.active) {
            Err(invalid(0))
        } else {
            Ok(())
        }
    }
    pub(crate) fn finish_owned(self) -> RenderMemoryStats {
        let mut stats = self.stats();
        drop(self);
        stats.live_bytes = 0;
        stats.token_array_bytes = 0;
        stats.reference_index_bytes = 0;
        stats.clip_copy_bytes = 0;
        stats.output_bytes = 0;
        stats
    }
}

#[cfg(test)]
mod raster_reservation_arithmetic {
    use super::*;
    struct Run;
    impl WorkControl for Run {
        fn charge(&mut self, _: WorkKind, _: u64) -> std::result::Result<(), Stop> {
            Ok(())
        }
        fn checkpoint(&mut self) -> std::result::Result<(), Stop> {
            Ok(())
        }
    }
    #[test]
    fn exhausted_history_count_and_lease_serial_never_allocate_or_change_live_storage() {
        let source = std::sync::Arc::new(Vec::new());
        let mut ledger = ChargeLedger::new(&source, 1 << 20, 64).unwrap();
        let lease = ledger.admit(AllocationTag::Output, 0).unwrap();
        ledger.release(lease).unwrap();
        let live = ledger.stats.live_bytes;
        ledger.stats.total_allocated_bytes = usize::MAX;
        assert_eq!(
            ledger
                .allocate::<u8>(AllocationTag::Output, 1, &mut Run)
                .unwrap_err()
                .kind,
            ErrorKind::Limit(LimitKind::Arithmetic)
        );
        assert_eq!(ledger.stats.live_bytes, live);
        assert_eq!(ledger.stats.total_allocated_bytes, usize::MAX);
        assert_eq!(ledger.stats().output_bytes, 0);
        ledger.stats.total_allocated_bytes = 0;
        ledger.stats.allocation_count = usize::MAX;
        assert!(ledger.allocate::<u8>(AllocationTag::Output, 1, &mut Run).is_err());
        assert_eq!(ledger.stats.live_bytes, live);
        assert_eq!(ledger.stats.total_allocated_bytes, 0);
        ledger.stats.allocation_count = 0;
        ledger.next = u64::MAX;
        assert!(ledger.allocate::<u8>(AllocationTag::Output, 1, &mut Run).is_err());
        assert_eq!(ledger.stats.live_bytes, live);
        assert!(ledger.entries.iter().all(|entry| !entry.active));
    }
}
use crate::memory::{add, bytes};
use crate::types::stopped;
use crate::*;
impl RasterScratch {
    /// Actual owned buffer capacities, including per-shape stroke grids.
    pub fn storage_bytes(&self, control: &mut dyn WorkControl) -> Result<usize> {
        control.checkpoint().map_err(stopped)?;
        let mut total = 0;
        macro_rules! count {
            ($values:expr) => {
                total = add(total, bytes($values)?)?;
            };
        }
        count!(&self.bounds.shapes);
        count!(&self.boundary.bits);
        count!(&self.scanlines.events);
        count!(&self.scanlines.nodes);
        count!(&self.scanlines.roots);
        count!(&self.scanlines.shape_events);
        count!(&self.scanlines.shape_nodes);
        count!(&self.rows.shape_offsets);
        count!(&self.rows.active_edges);
        count!(&self.rows.active_shapes);
        count!(&self.fill.eligible_shapes);
        count!(&self.fill.crossings);
        count!(&self.fill.intervals);
        count!(&self.fill.pixel_runs);
        count!(&self.local_edges);
        count!(&self.dash_seams);
        count!(&self.dash.segments);
        count!(&self.dash.joins);
        count!(&self.dash.shapes);
        count!(&self.center_samples);
        count!(&self.subpixel_samples);
        count!(&self.stroke_cost);
        for range in &self.dash.shapes {
