            scene,
            resolved.paint,
            &resolved.stops,
            resolved.template.as_ref(),
            false,
            control,
        )
    }
    pub fn append_resolved_stroke(
        &mut self,
        scene: SceneId,
        resolved: &ResolvedPaint,
        control: &mut dyn WorkControl,
    ) -> Result<usize> {
