impl RasterJob {
    pub fn owner_identity(&self) -> LedgerIdentity { self.ledger.owner_identity() }
    pub(crate) fn publish_pattern_output(&mut self, output: JobRenderOutput,
        builder: &mut SceneBuilder, scene: SceneId, descriptor: PatternDescriptor,
        control: &mut dyn WorkControl) -> Result<PatternId>
    {
        output.validate(self)?;
        self.validate_source(builder.source_owner())?;
        let old = self.checked(output.pixels)?.data.bytes()?;
        if old > 16 * 1024 * 1024 { return Err(limit(LimitKind::Patterns)); }
        control.checkpoint().map_err(stopped)?;
        let storage = std::mem::replace(&mut self.slots[output.pixels.slot].data,
            private::Storage::Byte(Vec::new()));
        let private::Storage::Byte(values) = storage else { return Err(invalid(0)); };
        let result = (|| {
            let tile = vexel_raster::Tile::from_owned_rgba(output.width, output.height, values)
                .map_err(|_| invalid(0))?;
            builder.append_pattern(scene, Pattern { tile, definition: descriptor.definition,
                tile_width: descriptor.tile_width, tile_height: descriptor.tile_height,
                content_transform: descriptor.content_transform }, control)
        })();
        // Storage is now either builder-owned and charged there, or dropped.
        // Keep its job charge until the ownership handoff finishes.
        self.pools[RasterPool::Output as usize] -= old;
        self.release_slot(output.pixels.slot)?;
        result
    }
    /// Move the SAME source/job ledger used by the coordinator into its owner.
    /// Rejects existing external leases: every live resource must be job-owned.
    pub fn new(ledger: ChargeLedger) -> std::result::Result<Self, JobStartError> {
        if let Err(diagnostic) = ledger.require_no_leases() {
            return Err(JobStartError { diagnostic, ledger });
        }
        Ok(Self {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::paint(self, scene, &value, control)?;
        room!(self, i, stroke_paints, 1, self.limits.shapes, 0);
        control.checkpoint().map_err(stopped)?;
        let index = self.scenes[i].stroke_paints.len();
        self.scenes[i].stroke_paints.push(value);
        Ok(index)
    }
    pub fn append_filter(
        &mut self,
        scene: SceneId,
        mut value: Filter,
        primitives: &[FilterPrimitive],
        control: &mut dyn WorkControl,
    ) -> Result<FilterId> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::filter(value, primitives, control)?;
        for p in primitives {
            if p.source_offset > self.source.len() {
                return Err(invalid(p.source_offset));
            }
        }
        if self.scenes[i].filters.len() >= self.limits.filters {
            return Err(limit(LimitKind::Filters));
        }
        let serial = self.serial()?;
        room!(self, i, filters, 1, self.limits.filters, 0);
        room!(self, i, filters_serials, 1, self.limits.filters, 0);
        room!(self, i, filter_primitives, primitives.len(), 65536, 0);
        let mark = self.checkpoint_internal(scene)?;
        value.primitives = TableRange {
            first: self.scenes[i].filter_primitives.len(),
            count: primitives.len(),
        };
        for primitive in primitives {
            if let Err(stop) = control.charge(WorkKind::FilterPixel, 1) {
                self.rollback_internal(mark)?;
                return Err(stopped(stop));
            }
            self.scenes[i].filter_primitives.push(*primitive);
        }
        let id = FilterId {
            owner: self.owner,
            scene: scene.slot,
            slot: self.scenes[i].filters.len() as u32,
            serial,
        };
        self.scenes[i].filters.push(value);
        self.scenes[i].filters_serials.push(serial);
